<?php
return static function(Router $r,array $c):void{
 $ctx=function()use($c){$p=Database::connection($c['db']);return [$p,Auth::requireRoles($p,['admin','librarian'])];};
 $r->add('GET','/api/inventory',function()use($ctx){[$p,$u]=$ctx();Response::json(['copies'=>$p->query('SELECT b.*,s.ten_sach,v.ma_vi_tri FROM ban_sach b JOIN sach s USING(sach_id) JOIN vi_tri_luu_tru v USING(vi_tri_id) ORDER BY b.ban_sach_id')->fetchAll(),'checks'=>$p->query('SELECT x.*,b.ma_ban_sach,t.email FROM inventory_check x JOIN ban_sach b USING(ban_sach_id) JOIN tai_khoan t ON t.tai_khoan_id=x.checked_by ORDER BY inventory_id DESC LIMIT 200')->fetchAll()]);});
 $r->add('POST','/api/inventory',function()use($ctx){[$p,$u]=$ctx();$d=Input::body();$id=Input::id($d['ban_sach_id']??null);$status=$d['observed_status']??'';if(!in_array($status,['available','borrowed','damaged','lost'],true))throw new ApiException(422,'INVALID_STATUS','Tình trạng không hợp lệ.');$note=Input::text($d,'note',1000);
  Input::transaction($p,function()use($p,$u,$id,$status,$note){$b=Input::query($p,'SELECT * FROM ban_sach WHERE ban_sach_id=? FOR UPDATE',[$id])->fetch();if(!$b)throw new ApiException(404,'NOT_FOUND','Không có bản sách.');$loan=Input::query($p,"SELECT 1 FROM loan_item WHERE ban_sach_id=? AND status='borrowed'",[$id])->fetch();if(($loan&&$status!=='borrowed')||(!$loan&&$status==='borrowed'))throw new ApiException(409,'ACTIVE_LOAN','Tình trạng đang mượn phải khớp phiếu; dùng luồng trả/mất/hỏng để xử lý.');Input::query($p,'INSERT INTO inventory_check(ban_sach_id,observed_status,note,checked_by,created_at) VALUES (?,?,?,?,UTC_TIMESTAMP())',[$id,$status,$note,$u['tai_khoan_id']]);Input::query($p,'UPDATE ban_sach SET tinh_trang=? WHERE ban_sach_id=?',[$status,$id]);Input::audit($p,'inventory.check',(string)$id);});Response::json(['saved'=>true]);});
};
